const photoUrl = (id: string) =>
  `https://images.unsplash.com/photo-${id}?auto=format&fit=crop&w=720&q=83`;

const stillLife = [
  '1494438639946-1ebd1d20bf85',
  '1490481651871-ab68de25d43d',
  '1600210492486-724fe5c67fb0',
  '1616486338812-3dadae4b4ace',
  '1600607687920-4e2a09cf159d',
  '1616486029423-aaa4789e8c9a',
].map(photoUrl);

const landscapes = [
  '1470770841072-f978cf4d019e',
  '1500534623283-312aade485b7',
  '1500530855697-b586d89ba3ee',
  '1472214103451-9374bd1c798e',
  '1483985988355-763728e1935b',
  '1470071459604-3b5ec3a7fe05',
  '1441974231531-c6227db76b6e',
  '1501785888041-af3ef285b470',
].map(photoUrl);

const cursorPhotos = [
  '1518005020951-eccb494ad742',
  '1518837695005-2083093ee35b',
  '1501785888041-af3ef285b470',
  '1616486338812-3dadae4b4ace',
].map(photoUrl);

const paleStage =
  'bg-[#e8dfd0] text-[#42382e] bg-[radial-gradient(ellipse_at_20%_8%,#f8f3e9,transparent_62%)]';
const darkStage =
  'bg-[#272e27] text-[#f9f3e7] bg-[radial-gradient(ellipse_at_8%_0%,#4d5747,transparent_70%)]';
const hint = (
  <p className='pointer-events-none text-center text-sm font-medium'>
    Move or drag to reveal the trail
  </p>
);

function isStamp(id: StampId | CanvasEffect): id is StampId {
  return Object.hasOwn(stampEffects, id);
}

function ExampleStage({ example }: { example: Example }) {
  if (example.group === 'originals') {
    const Original = originals[example.id];
    return <Original />;
  }

  if (example.group === 'codepen') {
    return (
      <ImageMouseTrail
        items={cursorPhotos}
        effect={stampEffects[example.id]}
        threshold={100}
        minInterval={70}
        maxNumberOfImages={18}
        duration={1200}
        touchAction='none'
        imgClass='mt-10 h-48 w-32 rounded-sm shadow-xl sm:mt-[75px] sm:h-[300px] sm:w-[200px]'
        className='h-[clamp(300px,55vw,520px)] bg-[#eeedf5] text-[#332d43] bg-[radial-gradient(ellipse_at_18%_12%,#fffaf4,transparent_70%)]'
      >
        {hint}
      </ImageMouseTrail>
    );
  }

  if (isStamp(example.id)) {
    if (example.id === 'image-slide') {
      return (
        <div className='relative isolate overflow-hidden rounded-lg bg-[#242b26]'>
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img
            src={stillLife[0]}
            alt=''
            className='pointer-events-none absolute inset-0 size-full object-cover'
          />
          <ImageMouseTrail
            items={stillLife}
            effect={stampEffects[example.id]}
            threshold={100}
            maxNumberOfImages={4}
            duration={740}
            touchAction='none'
            imgClass='size-full'
            className='h-[clamp(300px,55vw,520px)] bg-transparent text-white'
          >
            <p className='pointer-events-none mx-auto w-fit rounded-md bg-black/65 px-3 py-2 text-sm font-medium'>
              Move sideways to change the picture
            </p>
          </ImageMouseTrail>
        </div>
      );
    }

    return (
      <ImageMouseTrail
        items={example.group === 'image' ? stillLife : landscapes}
        effect={stampEffects[example.id]}
        threshold={example.id === 'motion-persistence' ? 56 : 64}
        maxNumberOfImages={11}
        duration={example.id === 'motion-classic' ? 800 : 1420}
        touchAction='none'
        imgClass='h-32 w-24 rounded-sm border border-white/30 shadow-lg sm:h-48 sm:w-36'
        className={`h-[clamp(300px,55vw,520px)] ${example.group === 'image' ? paleStage : darkStage}`}
      >
        {hint}
      </ImageMouseTrail>
    );
  }

  return (
    <div
      className={`relative isolate grid h-[clamp(300px,55vw,520px)] touch-none place-items-center overflow-hidden rounded-lg ${darkStage}`}
    >
      {hint}
      <TrailCanvas effect={example.id} images={landscapes} />
    </div>
  );
}

function exampleSource(example: Example) {
  if (example.group === 'originals') return;
  if (example.group === 'codepen') {
    return {
      href: 'https://codepen.io/thingbynemanja/full/ogjaaNE',
      label: 'CodePen by Nemanja Kočović',
    };
  }

  const { group, demo } = example;
  const collection =
    group === 'image' ? 'ImageTrailEffects/blob/master' : 'MotionTrailAnimations/blob/main';
  return {
    href: `https://github.com/codrops/${collection}/index${demo === 1 ? '' : demo}.html`,
    label: `Codrops demo ${demo}`,
  };
}

export default function MousetrailExplorer() {
  const id = useId();
  const [index, setIndex] = useState(0);
  const example = examples[index];
  const source = exampleSource(example);
  const canvasAdaptation = example.group === 'motion' && !isStamp(example.id);

  function step(amount: number) {
    setIndex((value) => (value + amount + examples.length) % examples.length);
  }

  return (
    <section aria-label='Image trail explorer' className='not-prose grid w-full gap-3'>
      <div className='flex flex-wrap items-end justify-between gap-3'>
        <div className='grid min-w-0 flex-1 gap-1.5'>
          <label htmlFor={id} className='text-sm font-medium'>
            Explore examples
          </label>
          <select
            id={id}
            value={example.id}
            onChange={(event) => {
              const next = examples.findIndex((entry) => entry.id === event.target.value);
              if (next >= 0) setIndex(next);
            }}
            className='h-10 w-full max-w-xs rounded-md border bg-background px-2.5 text-sm text-foreground'
          >
            {(Object.keys(groups) as (keyof typeof groups)[]).map((group) => (
              <optgroup key={group} label={groups[group]}>
                {examples
                  .filter((entry) => entry.group === group)
                  .map((entry) => (
                    <option key={entry.id} value={entry.id}>
                      {entry.title}
                    </option>
                  ))}
              </optgroup>
            ))}
          </select>
        </div>
        <div className='flex shrink-0 items-center gap-2'>
          <button
            type='button'
            aria-label='Previous example'
            onClick={() => step(-1)}
            className='grid size-10 cursor-pointer place-items-center rounded-md border text-lg hover:bg-muted'
          >
            <span aria-hidden='true'>←</span>
          </button>
          <span
            aria-hidden='true'
            className='min-w-12 text-center text-sm tabular-nums text-muted-foreground'
          >
            {index + 1}/{examples.length}
          </span>
          <button
            type='button'
            aria-label='Next example'
            onClick={() => step(1)}
            className='grid size-10 cursor-pointer place-items-center rounded-md border text-lg hover:bg-muted'
          >
            <span aria-hidden='true'>→</span>
          </button>
        </div>
      </div>
      <div data-trail-example={example.id}>
        <Suspense
          fallback={
            <p
              role='status'
              className='grid min-h-80 place-items-center rounded-lg bg-muted text-sm'
            >
              Loading preview…
            </p>
          }
        >
          <ExampleStage key={example.id} example={example} />
        </Suspense>
      </div>
      <div className='flex flex-wrap items-baseline justify-between gap-2 text-sm text-muted-foreground'>
        <p aria-live='polite'>
          {example.title}. {example.description}
          {canvasAdaptation && ' Canvas adaptation.'}
        </p>
        {source && (
          <a
            href={source.href}
            target='_blank'
            rel='noreferrer'
            className='underline underline-offset-4'
          >
            {source.label}
          </a>
        )}
      </div>
    </section>
  );
}

import type { ImageTrailEffect } from '@/components/ui/mousetrail';

type Sample = Parameters<ImageTrailEffect['keyframes']>[0];

const settle = 'cubic-bezier(0.18, 1, 0.35, 1)';
const fall = 'cubic-bezier(0.53, 0.02, 0.85, 0.68)';

function frame(
  offset: number,
  opacity = 1,
  x = 0,
  y = 0,
  scale = 1,
  rotation = 0,
  extra: Keyframe = {}
): Keyframe {
  return {
    offset,
    opacity,
    transform: `translate(-50%, -50%) translate(${x}px, ${y}px) rotate(${rotation}deg) scale(${scale})`,
    ...extra,
  };
}

function approach({ delta }: Pick<Sample, 'delta'>, scale = 1, extra?: Keyframe) {
  return frame(0, 1, -delta.x * 0.7, -delta.y * 0.7, scale, 0, extra);
}

export const stampEffects = {
  'cursor-trailer': {
    keyframes: () => {
      const tilt = Math.random() * 40 - 20;
      return [
        frame(0, 1, 0, 0, 0, tilt, { easing: 'cubic-bezier(0.34, 1.7, 0.64, 1)' }),
        frame(0.5, 1, 0, 0, 1, tilt, { easing: 'cubic-bezier(0.33, 0, 0.67, 0)' }),
        frame(1, 1, 0, 0, 0, tilt),
      ];
    },
  },
  'image-shrink': {
    keyframes: (sample) => [approach(sample), frame(0.3), frame(1, 0, 0, 0, 0.2)],
  },
  'image-bloom': {
    keyframes: (sample) => [
      approach(sample),
      frame(0.48),
      frame(1, 0, 0, 0, 2, 0, { filter: 'blur(3px)' }),
    ],
  },
  'image-fall': {
    keyframes: (sample) => [
      approach(sample),
      frame(0.34, 1, 0, 0, 1, 0, { easing: fall }),
      frame(1, 0, 0, sample.height * 0.52),
    ],
  },
  'image-stretch': {
    keyframes: ({ height }) => [
      frame(0),
      frame(0.32, 1, 0, 0, 1, 0, { easing: fall }),
      {
        offset: 0.55,
        opacity: 0.82,
        transform: 'translate(-50%, -50%) translateY(20px) scale(0.55, 1.95)',
        transformOrigin: 'center top',
        easing: fall,
      },
      {
        offset: 1,
        opacity: 0,
        transform: `translate(-50%, -50%) translateY(${height * 0.55}px) scale(0.75, 1.55)`,
        transformOrigin: 'center top',
      },
    ],
  },
  'image-slide': {
    anchor: 'center',
    persist: true,
    keyframes: ({ delta }) => [
      frame(0, 1, Math.sign(delta.x || 1) * 108, 0, 1.12, 0, { easing: settle }),
      frame(1, 1, 0, 0, 1.12),
    ],
  },
  'motion-classic': {
    keyframes: (sample) => [
      frame(0, 1, -sample.delta.x, -sample.delta.y),
      frame(0.55, 1, 0, 0, 1, 0, { easing: fall }),
      frame(1, 0, 0, 0, 0.2),
    ],
  },
  'motion-innerscape': {
    keyframes: (sample) => [
      approach(sample, 0.36, { clipPath: 'inset(38% 38%)', filter: 'brightness(2.5)' }),
      frame(0.4, 1, 0, 0, 1, 0, { clipPath: 'inset(0%)', filter: 'brightness(1)' }),
      frame(0.62, 1, 0, 0, 1, 0, { clipPath: 'inset(0%)', filter: 'brightness(1)' }),
      frame(1, 0, 0, 0, 0.2, 0, { clipPath: 'inset(0%)', filter: 'brightness(1)' }),
    ],
  },
  'motion-exiting': {
    keyframes: (sample) => [
      approach(sample, 0.12),
      frame(0.38),
      frame(0.58, 1, 0, 0, 1, 0, { easing: fall }),
      frame(1, 0, sample.index % 2 ? 34 : -34, -sample.height * 0.48, 0.2),
    ],
  },
  'motion-flow': {
    keyframes: (sample) => {
      const { x, y } = sample.delta;
      const light = 1 + sample.speed * 0.4;
      return [
        approach(sample, 0.12, { filter: `brightness(${light}) contrast(${light})` }),
        frame(0.28, 1, x * 0.28, y * 0.28, 1, 0, { filter: 'brightness(1) contrast(1)' }),
        frame(1, 0, x * 2, y * 2, 1, 0, { filter: 'brightness(1) contrast(1)' }),
      ];
    },
  },
  'motion-spin': {
    keyframes: ({ delta: { x, y } }) => {
      const angle = (Math.atan2(y, x || 0.01) * 180) / Math.PI;
      return [
        frame(0, 0.9, -x, -y, 0.15, angle - 135),
        frame(0.54, 1, x * 0.6, y * 0.6, 1, angle - 20),
        frame(1, 0, x * 1.8, y * 1.8, 1, angle + 28),
      ];
    },
  },
  'motion-velocity': {
    keyframes: (sample) => {
      const strength = Math.min(1, sample.speed / 2);
      const filter = `grayscale(${1 - strength}) brightness(${0.65 + strength * 0.65}) blur(${(1 - strength) * 8}px)`;
      return [
        approach(sample, 0.12, { filter }),
        frame(0.5, 1, 0, 0, 0.48 + strength * 1.05, 0, { filter }),
        frame(1, 0, 0, 0, 0.2, 0, { filter }),
      ];
    },
  },
  'motion-persistence': {
    persist: true,
    keyframes: (sample) => {
      const scale = 0.62 + ((sample.index * 13) % 17) / 34;
      return [approach(sample, scale * 0.55), frame(1, 1, 0, 0, scale)];
    },
  },
  'motion-perspective': {
    keyframes: ({ position, width, height, delta }) => {
      const x = position.x / width - 0.5;
      const y = position.y / height - 0.5;
      const depth = Math.hypot(x, y) * 200;
      const tilt = `perspective(520px) rotateY(${x * 70}deg) rotateX(${-y * 65}deg) translateZ(${depth}px)`;
      return [
        approach({ delta }, 0.8),
        frame(0.54, 1, 0, 0, 1, 0, { transform: `translate(-50%, -50%) ${tilt}` }),
        frame(1, 0, 0, 0, 1, 0, { transform: `translate(-50%, -50%) ${tilt} scale(1.12)` }),
      ];
    },
  },
} satisfies Record<string, ImageTrailEffect>;

'use client';

import { useEffect, useRef, useState } from 'react';
import ImageMouseTrail from '@/components/ui/mousetrail';
import {
  cropPicture,
  drawGooConnections,
  drawPhoto,
  drawStamp,
  type Brush,
  type CanvasEffect,
  type TrailPicture,
  type TrailStamp,
} from './trail-canvas-draw';

type Point = { x: number; y: number };
const distance = (a: Point, b: Point) => Math.hypot(a.x - b.x, a.y - b.y);
const mix = (a: Point, b: Point, amount: number) => ({
  x: a.x + (b.x - a.x) * amount,
  y: a.y + (b.y - a.y) * amount,
});

const settings: Record<CanvasEffect, { lifetime: number; spacing: number; limit: number }> = {
  'motion-tile': { lifetime: 720, spacing: 45, limit: 12 },
  'motion-strata': { lifetime: 1750, spacing: 74, limit: 9 },
  'motion-tail': { lifetime: 650, spacing: 50, limit: 8 },
  'motion-silk': { lifetime: 1550, spacing: 86, limit: 6 },
  'motion-liquid': { lifetime: 1480, spacing: 72, limit: 6 },
  'motion-dust': { lifetime: 2100, spacing: 90, limit: 6 },
  'motion-gooey': { lifetime: 1450, spacing: 34, limit: 10 },
  'motion-swirl': { lifetime: 1500, spacing: 75, limit: 6 },
};

function pointAlong(path: Point[], offset: number) {
  for (let i = 1; i < path.length; i++) {
    const segment = distance(path[i - 1], path[i]);
    if (segment && offset <= segment) return mix(path[i - 1], path[i], offset / segment);
    offset -= segment;
  }
  return path[path.length - 1];
}

function drawTail(
  brush: Brush,
  photos: TrailPicture[],
  path: Point[],
  presence: number,
  rest: number
) {
  const { context: ctx, size } = brush;
  const count = Math.min(8, photos.length);
  const spacing = Math.min(48, size.x * 0.36) * (1 - rest) * presence;
  for (let i = count - 1; i >= 0; i--) {
    const point = pointAlong(path, spacing * i);
    const next = pointAlong(path, spacing * i + 8);
    const lean = Math.max(-0.15, Math.min(0.15, (point.x - next.x) * 0.018));
    const scale = 1 - i * 0.075;
    const width = size.x * scale;
    const height = size.y * scale;
    ctx.save();
    ctx.translate(point.x, point.y);
    ctx.rotate(lean);
    ctx.globalAlpha = presence * (i === 0 ? 1 : (1 - rest) * (1 - i * 0.07));
    drawPhoto(ctx, photos[i], -width / 2, -height / 2, width, height);
    ctx.restore();
  }
}

export default function TrailCanvas({
  effect,
  images,
}: {
  effect: CanvasEffect;
  images: string[];
}) {
  const ref = useRef<HTMLCanvasElement>(null);
  const [unavailable, setUnavailable] = useState(false);

  useEffect(() => {
    const canvas = ref.current;
    const stage = canvas?.parentElement;
    if (!canvas || !stage) return;
    const context = canvas.getContext('2d');
    if (!context) {
      setUnavailable(true);
      return;
    }
    const ctx = context;

    const photos = new Map<string, TrailPicture>();
    const media = window.matchMedia('(prefers-reduced-motion: reduce)');
    const { lifetime, spacing, limit } = settings[effect];
    let stamps: TrailStamp[] = [];
    let frame = 0;
    let width = 0;
    let height = 0;
    let dpr = 1;
    let size = { x: 144, y: 180 };
    let pointer: Point | null = null;
    let previousPointer: Point | null = null;
    let sampled: Point | null = null;
    let velocity = { x: 0, y: 0 };
    let movedAt = -Infinity;
    let prevTime = 0;
    let id = 0;
    let path: Point[] = [];
    let showTail = 0;

    const reset = () => {
      cancelAnimationFrame(frame);
      frame = 0;
      pointer = previousPointer = sampled = null;
      stamps = [];
      path = [];
      showTail = 0;
      movedAt = -Infinity;
      prevTime = 0;
      velocity = { x: 0, y: 0 };
      ctx.clearRect(0, 0, width, height);
    };

    const resize = () => {
      const newWidth = stage.clientWidth;
      const newHeight = stage.clientHeight;
      const newDpr = Math.min(window.devicePixelRatio || 1, 2);
      if (width === newWidth && height === newHeight && dpr === newDpr) return;
      reset();
      width = newWidth;
      height = newHeight;
      dpr = newDpr;
      canvas.width = Math.max(1, Math.round(width * dpr));
      canvas.height = Math.max(1, Math.round(height * dpr));
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      const cardWidth = Math.min(166, Math.max(74, width * 0.2));
      size = { x: cardWidth, y: cardWidth / 0.8 };
    };

    function queueFrame() {
      if (!frame) frame = requestAnimationFrame(render);
    }

    function render(now: number) {
      frame = 0;
      const elapsed = prevTime ? Math.min(50, now - prevTime) : 16;
      prevTime = now;
      const reduced = media.matches;
      const available = [...photos.values()];
      if (!available.length || !width || !height) return;
      ctx.clearRect(0, 0, width, height);
      const wantTail = effect === 'motion-tail' && !reduced;
      const timeSinceMove = Math.max(0, now - movedAt);

      if (pointer && wantTail) {
        const head = path[0] ? mix(path[0], pointer, 1 - 0.7 ** (elapsed / 16)) : pointer;
        if (!path.length || distance(head, path[0]) > 1) {
          path.unshift(head);
          if (path.length > 240) path.pop();
        }
        showTail = Math.min(1, showTail + elapsed / 220);
      }

      if (wantTail && path.length) {
        const rest = Math.min(1, Math.max(0, (timeSinceMove - 300) / 370));
        const presence = showTail * Math.max(0, 1 - (timeSinceMove - 625) / 360);
        if (presence > 0) {
          drawTail(
            { context: ctx, size, pointer: pointer || path[0], velocity, now },
            available,
            path,
            Math.min(showTail, presence),
            rest
          );
          queueFrame();
        } else {
          path = [];
          showTail = 0;
        }
        return;
      }

      const activeLifetime = reduced ? 540 : lifetime;
      stamps = stamps.filter((stamp) => now - stamp.born < activeLifetime);
      if (pointer) {
        const length = sampled ? distance(pointer, sampled) : 0;
        const step = reduced ? Math.max(75, spacing) : spacing;
        if (!sampled || length >= step) {
          const start = sampled || pointer;
          const count = sampled ? Math.min(3, Math.floor(length / step)) : 1;
          const direction = length
            ? { x: (pointer.x - start.x) / length, y: (pointer.y - start.y) / length }
            : { x: 1, y: 0 };
          for (let i = 1; i <= count; i++) {
            sampled = mix(start, pointer, length && count < 3 ? (step * i) / length : i / count);
            stamps.push({
              image: available[id % available.length],
              position: sampled,
              direction,
              born: now,
              seed: id++,
            });
          }
          stamps = stamps.slice(-limit);
        }
      }

      velocity = mix(velocity, { x: 0, y: 0 }, Math.min(1, elapsed / 150));
      const brush = {
        context: ctx,
        size,
        now,
        pointer: pointer || previousPointer || { x: -1000, y: -1000 },
        velocity,
      };
      if (effect === 'motion-gooey' && !reduced) drawGooConnections(brush, stamps, activeLifetime);
      stamps.forEach((stamp) => drawStamp(brush, stamp, effect, activeLifetime, reduced));
      if (stamps.length) queueFrame();
    }

    const preload = [...new Set(images)].map((src) => {
      const image = new Image();
      const ready = () => {
        if (!image.naturalWidth) return;
        photos.set(src, cropPicture(image));
        if (pointer) queueFrame();
      };
      image.onload = ready;
      image.src = src;
      if (image.complete) ready();
      return image;
    });

    const leave = () => {
      pointer = null;
      sampled = null;
      previousPointer = null;
      movedAt = Math.min(movedAt, performance.now() - 300);
    };

    const input = (event: PointerEvent) => {
      if (!event.isPrimary || (event.pointerType === 'touch' && !event.buttons)) return;
      const rect = stage.getBoundingClientRect();
      if (!rect.width || !rect.height) return;
      const point = {
        x: ((event.clientX - rect.left) * width) / rect.width,
        y: ((event.clientY - rect.top) * height) / rect.height,
      };
      if (point.x < 0 || point.y < 0 || point.x > width || point.y > height) {
        leave();
        return;
      }
      const now = performance.now();
      if (previousPointer) {
        const dt = Math.max(10, now - movedAt);
        const clampSpeed = (value: number) => Math.max(-2.5, Math.min(2.5, value / dt));
        velocity = {
          x: clampSpeed(point.x - previousPointer.x),
          y: clampSpeed(point.y - previousPointer.y),
        };
      }
      if (effect === 'motion-tail' && now - movedAt > 985) {
        path = [];
        showTail = 0;
      }
      pointer = previousPointer = point;
      movedAt = now;
      queueFrame();
    };

    const release = (event: PointerEvent) => {
      if (event.isPrimary) leave();
    };
    const observer = new ResizeObserver(resize);
    observer.observe(stage);
    resize();
    stage.addEventListener('pointermove', input, { passive: true });
    stage.addEventListener('pointerleave', release);
    stage.addEventListener('pointerup', release);
    stage.addEventListener('pointercancel', release);
    window.addEventListener('blur', reset);
    window.addEventListener('resize', resize);
    media.addEventListener('change', reset);
    return () => {
      reset();
      observer.disconnect();
      preload.forEach((image) => {
        image.onload = null;
      });
      stage.removeEventListener('pointermove', input);
      stage.removeEventListener('pointerleave', release);
      stage.removeEventListener('pointerup', release);
      stage.removeEventListener('pointercancel', release);
      window.removeEventListener('blur', reset);
      window.removeEventListener('resize', resize);
      media.removeEventListener('change', reset);
    };
  }, [effect, images]);

  if (unavailable) {
    return (
      <ImageMouseTrail
        items={images}
        fadeAnimation
        touchAction='none'
        className='pointer-events-auto absolute inset-0 h-full bg-transparent'
      />
    );
  }

  return (
    <canvas
      ref={ref}
      aria-hidden='true'
      className='pointer-events-none absolute inset-0 size-full'
    />
  );
}

type Point = { x: number; y: number };

export type CanvasEffect =
  | 'motion-tile'
  | 'motion-strata'
  | 'motion-tail'
  | 'motion-silk'
  | 'motion-liquid'
  | 'motion-dust'
  | 'motion-gooey'
  | 'motion-swirl';

export type TrailPicture = {
  img: HTMLImageElement;
  x: number;
  y: number;
  cropWidth: number;
  cropHeight: number;
};

export type TrailStamp = {
  image: TrailPicture;
  position: Point;
  direction: Point;
  born: number;
  seed: number;
};

export type Brush = {
  context: CanvasRenderingContext2D;
  size: Point;
  pointer: Point;
  velocity: Point;
  now: number;
};

export function cropPicture(img: HTMLImageElement): TrailPicture {
  const width = Math.min(img.naturalWidth, img.naturalHeight * 0.8);
  const height = width / 0.8;
  return {
    img,
    x: (img.naturalWidth - width) / 2,
    y: (img.naturalHeight - height) / 2,
    cropWidth: width,
    cropHeight: height,
  };
}

const clamp = (value: number) => Math.min(1, Math.max(0, value));
const ease = (value: number) => 1 - (1 - clamp(value)) ** 3;
const fade = (value: number, start: number) => 1 - clamp((value - start) / (1 - start));
const noise = (seed: number) => {
  const n = Math.sin(seed * 127.1 + 17.17) * 43758.5453;
  return n - Math.floor(n);
};

export function drawPhoto(
  ctx: CanvasRenderingContext2D,
  image: TrailPicture,
  x: number,
  y: number,
  width: number,
  height: number
) {
  ctx.drawImage(
    image.img,
    image.x,
    image.y,
    image.cropWidth,
    image.cropHeight,
    x,
    y,
    width,
    height
  );
}

/** Draw a source tile into its own destination rectangle. */
function patch(
  ctx: CanvasRenderingContext2D,
  image: TrailPicture,
  u: number,
  v: number,
  uw: number,
  vh: number,
  x: number,
  y: number,
  width: number,
  height: number
) {
  ctx.drawImage(
    image.img,
    image.x + u * image.cropWidth,
    image.y + v * image.cropHeight,
    uw * image.cropWidth,
    vh * image.cropHeight,
    x,
    y,
    width,
    height
  );
}

function tiles({ context: ctx, size }: Brush, stamp: TrailStamp, time: number, dust: boolean) {
  const { x: width, y: height } = size;
  const cols = dust ? 14 : 5;
  const rows = dust ? 17 : 5;
  const cellWidth = width / cols;
  const cellHeight = height / rows;
  const { x: dx, y: dy } = stamp.direction;
  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < cols; col++) {
      const seed = stamp.seed * 1000 + row * cols + col;
      const random = noise(seed);
      const edge = (dx * (col / cols - 0.5) + dy * (row / rows - 0.5) + 1) / 2;
      const gather = dust ? 1 - ease((time - edge * 0.14) / 0.34) : 0;
      const split = ease(
        (time - (dust ? 0.38 + edge * 0.16 : 0.12) - random * 0.12) / (dust ? 0.38 : 0.68)
      );
      const spread = dust ? split * 118 - gather * 69 : split * 26;
      const scale = 1 - (dust ? 0.75 : 0.24) * Math.max(split, gather);
      const side = (random - 0.5) * Math.max(split, gather) * (dust ? 68 : 38);
      const x = col * cellWidth - width / 2 + dx * spread - dy * side;
      const y = row * cellHeight - height / 2 + dy * spread + dx * side;
      ctx.globalAlpha = (1 - split) * (1 - gather);
      patch(
        ctx,
        stamp.image,
        col / cols,
        row / rows,
        1 / cols,
        1 / rows,
        x,
        y,
        cellWidth * scale + 0.4,
        cellHeight * scale + 0.4
      );
    }
  }
}

function strata({ context: ctx, size }: Brush, stamp: TrailStamp, time: number) {
  const count = 13;
  const band = size.y / count;
  const { x: dx, y: dy } = stamp.direction;
  const angle = Math.atan2(dy, dx);
  ctx.rotate(angle);
  // Render the strips on the motion axis while keeping the picture upright.
  for (let i = 0; i < count; i++) {
    const middle = Math.abs((i + 0.5) / count - 0.5) * 2;
    const lag = 1 - ease((time - middle * 0.1) / 0.42);
    const drift = ease((time - 0.56 - middle * 0.14) / 0.28);
    const bend = Math.sin(time * 24 + i * 0.65) * lag * 12;
    ctx.globalAlpha = fade(time, 0.58 + middle * 0.12);
    ctx.save();
    ctx.translate(-lag * 54 + drift * 55 + bend, 0);
    ctx.beginPath();
    ctx.rect(-size.y, -size.y / 2 + i * band, size.y * 2, band + 0.7);
    ctx.clip();
    ctx.rotate(-angle);
    drawPhoto(ctx, stamp.image, -size.x / 2, -size.y / 2, size.x, size.y);
    ctx.restore();
  }
}

function triangle(
  ctx: CanvasRenderingContext2D,
  image: TrailPicture,
  size: Point,
  source: [Point, Point, Point],
  target: [Point, Point, Point]
) {
  const [a, b, c] = source;
  const [p, q, r] = target;
  const bx = b.x - a.x;
  const by = b.y - a.y;
  const cx = c.x - a.x;
  const cy = c.y - a.y;
  const det = bx * cy - cx * by;
  const xx = ((q.x - p.x) * cy - (r.x - p.x) * by) / det;
  const xy = ((r.x - p.x) * bx - (q.x - p.x) * cx) / det;
  const yx = ((q.y - p.y) * cy - (r.y - p.y) * by) / det;
  const yy = ((r.y - p.y) * bx - (q.y - p.y) * cx) / det;

  ctx.save();
  ctx.beginPath();
  const center = { x: (p.x + q.x + r.x) / 3, y: (p.y + q.y + r.y) / 3 };
  target.forEach((point, index) => {
    // Slight overlap fills hairline seams at antialiased triangle edges.
    const x = point.x + (point.x - center.x) * 0.045;
    const y = point.y + (point.y - center.y) * 0.045;
    if (index === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  });
  ctx.closePath();
  ctx.clip();
  ctx.transform(xx, yx, xy, yy, p.x - xx * a.x - xy * a.y, p.y - yx * a.x - yy * a.y);
  drawPhoto(ctx, image, 0, 0, size.x, size.y);
  ctx.restore();
}

type WarpEffect = 'motion-silk' | 'motion-liquid' | 'motion-swirl';

function warped(brush: Brush, stamp: TrailStamp, time: number, effect: WarpEffect) {
  const { context: ctx, size, velocity, pointer } = brush;
  const strength = Math.sin(Math.PI * Math.min(0.95, time + 0.15));
  const { x: dx, y: dy } = stamp.direction;
  const cols = 6;
  const rows = 7;
  const source: Point[] = [];
  const target: Point[] = [];
  for (let row = 0; row <= rows; row++) {
    for (let col = 0; col <= cols; col++) {
      const u = col / cols;
      const v = row / rows;
      const x = (u - 0.5) * size.x;
      const y = (v - 0.5) * size.y;
      source.push({ x: u * size.x, y: v * size.y });
      if (effect === 'motion-silk') {
        const along = dx * (u - 0.5) + dy * (v - 0.5);
        const wave = Math.sin(along * 15 - time * 14) * strength * 19;
        target.push({ x: x - dy * wave - dx * wave * 0.4, y: y + dx * wave - dy * wave * 0.4 });
      } else if (effect === 'motion-liquid') {
        const proximity = Math.exp(
          -Math.hypot(stamp.position.x + x - pointer.x, stamp.position.y + y - pointer.y) / 110
        );
        const wave = Math.sin(v * 14 - time * 13 + u * 4) * strength;
        target.push({
          x: x + wave * 18 + velocity.x * proximity * 17,
          y: y + Math.cos(u * 14 - time * 12) * strength * 11 + velocity.y * proximity * 17,
        });
      } else {
        const offsetX = x - dx * 18;
        const offsetY = y - dy * 18;
        const radius = Math.hypot(offsetX / size.x, offsetY / size.y);
        const turn = Math.max(0, 1 - radius * 1.45) * strength * (time * 4.9 + 0.6);
        target.push({
          x: offsetX * Math.cos(turn) - offsetY * Math.sin(turn) + dx * 18,
          y: offsetX * Math.sin(turn) + offsetY * Math.cos(turn) + dy * 18,
        });
      }
    }
  }
  ctx.globalAlpha = ease(time / 0.15) * fade(time, 0.55);
  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < cols; col++) {
      const a = row * (cols + 1) + col;
      const b = a + 1;
      const c = a + cols + 1;
      const d = c + 1;
      triangle(
        ctx,
        stamp.image,
        size,
        [source[a], source[b], source[c]],
        [target[a], target[b], target[c]]
      );
      triangle(
        ctx,
        stamp.image,
        size,
        [source[b], source[d], source[c]],
        [target[b], target[d], target[c]]
      );
    }
  }
}

function gooProfile(stamp: TrailStamp, now: number, lifetime: number) {
  const time = clamp((now - stamp.born) / lifetime);
  const swell = ease(time / 0.3);
  const wobble = Math.sin(time * 31) * (1 - swell) * 0.3;
  const scale = (0.08 + swell * (0.92 + wobble)) * (0.05 + 0.95 * fade(time, 0.58));
  return { scale, opacity: fade(time, 0.77) };
}

// The nearby stamps share soft, widening necks that disappear as the drops recede.
export function drawGooConnections(
  { context: ctx, size, now }: Brush,
  stamps: TrailStamp[],
  lifetime: number
) {
  for (let i = 1; i < stamps.length; i++) {
    const left = stamps[i - 1];
    const right = stamps[i];
    const a = gooProfile(left, now, lifetime);
    const b = gooProfile(right, now, lifetime);
    const gap = Math.hypot(right.position.x - left.position.x, right.position.y - left.position.y);
    const reach = (a.scale + b.scale) * size.x * 0.72;
    if (gap > reach || reach === 0) continue;
    ctx.save();
    ctx.globalAlpha = Math.min(a.opacity, b.opacity) * Math.sqrt(1 - gap / reach) * 0.7;
    ctx.strokeStyle = '#a5a895';
    ctx.lineCap = 'round';
    ctx.lineWidth = Math.min(a.scale, b.scale) * size.x * 0.63;
    ctx.beginPath();
    ctx.moveTo(left.position.x, left.position.y);
    ctx.lineTo(right.position.x, right.position.y);
    ctx.stroke();
    ctx.restore();
  }
}

export function drawStamp(
  brush: Brush,
  stamp: TrailStamp,
  effect: CanvasEffect,
  lifetime: number,
  reduced: boolean
) {
  const { context: ctx, size, now } = brush;
  const time = clamp((now - stamp.born) / lifetime);
  const { x, y } = stamp.position;
  ctx.save();
  ctx.translate(x, y);
  if (reduced) {
    ctx.globalAlpha = ease(time / 0.2) * fade(time, 0.4);
    drawPhoto(ctx, stamp.image, -size.x / 2, -size.y / 2, size.x, size.y);
  } else if (effect === 'motion-tile' || effect === 'motion-dust') {
    tiles(brush, stamp, time, effect === 'motion-dust');
  } else if (effect === 'motion-strata') {
    strata(brush, stamp, time);
  } else if (effect === 'motion-gooey') {
    const { scale, opacity } = gooProfile(stamp, now, lifetime);
    const width = size.x * scale;
    const height = size.y * scale;
    ctx.globalAlpha = opacity;
    ctx.beginPath();
    ctx.roundRect(-width / 2, -height / 2, width, height, width * (0.13 + 0.35 * (1 - scale)));
    ctx.clip();
    drawPhoto(ctx, stamp.image, -width / 2, -height / 2, width, height);
  } else if (effect !== 'motion-tail') {
    const glide = effect === 'motion-silk' ? ease(time) * 140 - 34 : -32 * (1 - ease(time));
    const scale = 0.82 + ease(time / 0.58) * 0.18;
    ctx.translate(stamp.direction.x * glide, stamp.direction.y * glide);
    ctx.scale(scale, scale);
    warped(brush, stamp, time, effect);
  }
  ctx.restore();
}
